        ];
        $maxTrend = max(1, $monthlyTrend->max('amount'));
        $maxCenter = max(1, $topCostCenters->max('amount'));
        $formatDays = fn ($value) => $value === null ? '—' : ($value < 1 ? number_format($value * 24, 1) . ' h' : number_format($value, 1) . ' d');
        $processable = $analyticsRows->filter(fn ($row) => !in_array($row['model']->status, ['borrador', 'rechazado'], true));
        $categoryTotals = $processable->groupBy(fn ($row) => $row['model']->category ?: 'Sin categoría')->map(fn ($rows, $category) => ['name' => $category, 'count' => $rows->count(), 'amount' => $rows->sum('total')])->sortByDesc('amount')->take(12)->values();
        $centerRanking = $analyticsRows->groupBy(fn ($row) => $row['model']->cost_center_id ?: 0)->map(function ($rows) use ($formatDays) {
            $model = $rows->first()['model'];
            $submitted = $rows->filter(fn ($row) => $row['submitted_at']);
            $chain = $rows->filter(fn ($row) => $row['submitted_at'] && $row['last_operational_approval_at'])->map(fn ($row) => $row['submitted_at']->diffInMinutes($row['last_operational_approval_at']) / 1440)->sort()->values();
            $n = $chain->count(); $middle = intdiv($n, 2);
            $median = $n ? ($n % 2 ? $chain[$middle] : ($chain[$middle - 1] + $chain[$middle]) / 2) : null;
            return ['center' => $model->costCenter, 'count' => $rows->whereNotIn('model.status', ['borrador', 'rechazado'])->count(), 'amount' => $rows->filter(fn ($row) => !in_array($row['model']->status, ['borrador', 'rechazado'], true))->sum('total'), 'ticket' => $rows->avg('total'), 'rejection_rate' => $submitted->count() ? $rows->where('model.status', 'rechazado')->count() / $submitted->count() : 0, 'rework_rate' => $submitted->count() ? $rows->filter(fn ($row) => $row['events']->contains(fn ($event) => in_array($event->action, ['rechazado', 'requiere_correccion'], true)))->count() / $submitted->count() : 0, 'approval_days' => $median];
        })->sortByDesc('amount')->values();
        $cxpAging = collect([[0, 7, '0–7 días'], [7, 14, '8–14 días'], [14, 30, '15–30 días'], [30, 60, '31–60 días'], [60, INF, '> 60 días']])->map(function ($bucket) use ($cxpBacklog) { [$from, $to, $label] = $bucket; $rows = $cxpBacklog->filter(function ($row) use ($from, $to) { $start = $row['last_operational_approval_at'] ?: $row['submitted_at']; $days = $start ? $start->diffInMinutes(now()) / 1440 : 0; return $days > $from && $days <= $to; }); return ['label' => $label, 'count' => $rows->count(), 'amount' => $rows->sum('total')]; });
        $approvalSla = $analyticsRows->flatMap(function ($row) { return $row['events']->filter(fn ($event) => in_array($event->action, ['aprobado', 'rechazado', 'requiere_correccion'], true) && $event->user)->map(function ($event, $index) use ($row) { $previous = $row['events']->filter(fn ($item) => $item->created_at->lt($event->created_at))->last(); $base = $previous?->created_at ?: $row['submitted_at']; return ['user' => $event->user, 'hours' => $base ? $base->diffInMinutes($event->created_at) / 60 : null]; }); })->filter(fn ($row) => $row['hours'] !== null)->groupBy(fn ($row) => $row['user']->id)->map(function ($rows) { $hours = $rows->pluck('hours')->sort()->values(); $n = $hours->count(); $middle = intdiv($n, 2); return ['name' => $rows->first()['user']->name, 'count' => $n, 'median_hours' => $n % 2 ? $hours[$middle] : ($hours[$middle - 1] + $hours[$middle]) / 2, 'late' => $hours->filter(fn ($hours) => $hours > 48)->count()]; })->filter(fn ($row) => $row['count'] >= 5)->sortByDesc(fn ($row) => $row['late'] / $row['count'])->take(15)->values();
        $complianceByRule = collect($complianceRules)->map(function ($rule, $code) use ($analyticsRows) { $rows = $analyticsRows->filter(fn ($row) => in_array($code, $row['rules'], true)); return $rule + ['code' => $code, 'count' => $rows->count(), 'amount' => $rows->sum('total')]; })->filter(fn ($rule) => $rule['count'])->values();
        $fractioned = $analyticsRows->filter(fn ($row) => $row['model']->type === 'fondo_fijo' && $row['model']->rfc_emisor && $row['model']->fecha && $row['total'] <= 2000)->groupBy(fn ($row) => implode('|', [$row['model']->rfc_emisor, $row['model']->user_id, $row['model']->fecha->toDateString()]))->filter(fn ($rows) => $rows->count() > 1 && $rows->sum('total') > 2000)->map(function ($rows) { $first = $rows->first()['model']; return ['rfc' => $first->rfc_emisor, 'user' => $first->user?->name ?: 'Sin solicitante', 'date' => $first->fecha, 'count' => $rows->count(), 'amount' => $rows->sum('total')]; })->sortByDesc('amount')->take(15)->values();
